node -v && node --input-type=module -e '
import { createPushGate } from "./bot.mjs";
const eq = (a, b, msg) => { if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(msg + ": " + JSON.stringify(a)); };
const tokyo = { id: "u_8841", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const T = (iso) => new Date(iso);
let g = createPushGate();
eq(g.attempt(tokyo, T("2026-10-23T03:00:00Z")), { allowed: true, reason: null }, "rule3 one allowed");
eq(g.attempt(tokyo, T("2026-10-23T14:30:00Z")).reason, null, "day ok 23:30 is quiet? no, 23:30 JST is quiet");
' 2>&1 | head -5; echo "---"; node --input-type=module -e '
import { createPushGate } from "./bot.mjs";
const eq = (a, b, msg) => { if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(msg + ": got " + JSON.stringify(a) + " want " + JSON.stringify(b)); };
const ok = { allowed: true, reason: null };
const no = (r) => ({ allowed: false, reason: r });
const T = (iso) => new Date(iso);
const tk = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };

let g = createPushGate();
eq(g.attempt(tk, T("2026-10-23T03:00:00Z")), ok, "12:00 JST allowed");
eq(g.attempt(tk, T("2026-10-23T14:00:00Z")), no("quiet_hours"), "23:00 JST quiet");
eq(g.attempt(tk, T("2026-10-23T13:00:00Z")), ok, "22:00 JST start inclusive -> quiet");
' 2>&1 | tail -3

node --input-type=module -e '
import { createPushGate } from "./bot.mjs";
const ok = { allowed: true, reason: null };
const no = (r) => ({ allowed: false, reason: r });
const T = (iso) => new Date(iso);
const check = (got, want, msg) => { if (JSON.stringify(got) !== JSON.stringify(want)) throw new Error(`${msg}: got ${JSON.stringify(got)} want ${JSON.stringify(want)}`); console.log("ok  " + msg); };
const tk = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };

let g = createPushGate();
check(g.attempt(tk, T("2026-10-23T03:00:00Z")), ok, "12:00 JST allowed (rule 3 one send)");
check(g.attempt(tk, T("2026-10-23T14:00:00Z")), no("quiet_hours"), "23:00 JST quiet (wrap)");
check(g.attempt(tk, T("2026-10-23T13:00:00Z")), no("quiet_hours"), "22:00 JST quiet, start inclusive");
check(g.attempt(tk, T("2026-10-23T21:59:00Z")), no("quiet_hours"), "06:59 JST quiet");
check(g.attempt(tk, T("2026-10-23T22:00:00Z")), ok, "07:00 JST allowed, end exclusive");

g = createPushGate();
check(g.attempt(tk, T("2026-10-23T03:00:00Z")), ok, "cap 1/3");
check(g.attempt(tk, T("2026-10-23T04:00:00Z")), ok, "cap 2/3");
check(g.attempt(tk, T("2026-10-23T05:00:00Z")), ok, "cap 3/3");
check(g.attempt(tk, T("2026-10-23T06:00:00Z")), no("daily_cap_reached"), "4th same local day refused");
check(g.attempt(tk, T("2026-10-24T03:00:00Z")), ok, "next local day resets cap");
check(g.attempt({ ...tk, id: "u2" }, T("2026-10-23T06:00:00Z")), ok, "other user independent");

const ny = { id: "u3", timeZone: "America/New_York", quietStart: "13:00", quietEnd: "14:00", dailyCap: 5 };
g = createPushGate();
check(g.attempt(ny, T("2026-10-23T17:30:00Z")), no("quiet_hours"), "13:30 EDT, non-wrapping window quiet");
check(g.attempt(ny, T("2026-10-23T18:00:00Z")), ok, "14:00 EDT allowed, end exclusive");
check(g.attempt({ ...ny, quietStart: "09:00", quietEnd: "09:00" }, T("2026-10-23T13:00:00Z")), ok, "start==end means no quiet");

g = createPushGate();
check(g.attempt({ ...tk, timeZone: "Mars/Olympus" }, T("2026-10-23T03:00:00Z")), no("invalid_time_zone"), "bad zone held");
check(g.attempt({ ...tk, quietStart: "25:00" }, T("2026-10-23T03:00:00Z")), no("invalid_quiet_hours"), "bad quiet time held");
check(g.attempt({ ...tk, dailyCap: undefined }, T("2026-10-23T03:00:00Z")), no("invalid_daily_cap"), "missing cap held");
check(g.attempt({ ...tk, dailyCap: 0 }, T("2026-10-23T03:00:00Z")), no("daily_cap_reached"), "cap 0 allows nothing");
check(g.attempt(tk, new Date("nope")), no("invalid_time"), "invalid Date held");
check(g.attempt({ ...tk, id: "" }, T("2026-10-23T03:00:00Z")), no("invalid_user"), "empty id held");
console.log("all checks passed");
' 2>&1
